// F5Bot manda un email por keyword con enlaces a Reddit/HN/Lobsters que la mencionan.
// Formato típico del cuerpo: título + URL por línea, agrupado por keyword.
const items = [];
for (const item of $input.all()) {
  const subject = item.json.subject || '';
  const bodyText = item.json.textPlain || item.json.text || '';
  // Extrae pares (título, url) — F5Bot pone la URL en la misma línea o la siguiente
  const urlRe = /(https?:\/\/(?:www\.)?(?:reddit\.com|news\.ycombinator\.com|lobste\.rs)\S+)/g;
  const matches = [...bodyText.matchAll(urlRe)];
  const keywordMatch = subject.match(/F5Bot:\s*(.+)/i);
  const keyword = keywordMatch ? keywordMatch[1].trim() : subject;
  for (const m of matches) {
    items.push({ json: { keyword, url: m[1], rawSubject: subject } });
  }
}
return items;

